begin;
select set_config('request.jwt.claim.sub','2d50291d-03e3-46a3-b3d8-c4550bc1bce7',true);
do $test$
declare test_user uuid:=gen_random_uuid();work uuid;work2 uuid;parent_id uuid;type_id text;cat text;lot text:='TEST-WAGE-'||substr(gen_random_uuid()::text,1,8);office text;mandor text;bank text;parents jsonb;details jsonb;entries jsonb;a uuid;b uuid;pay uuid;ret uuid;key uuid;data jsonb;failed boolean;today date:=(now() at time zone 'Asia/Jakarta')::date;n integer;
begin
 insert into auth.users(id,email) values(test_user,'wage-test-'||test_user::text||'@example.invalid');
 insert into user_profiles(user_id,role,status_aktif,nama) values(test_user,'KEUANGAN',true,'TEST WAGE') on conflict(user_id) do update set role='KEUANGAN',status_aktif=true;
 select id_kantor,id_mandor into office,mandor from master_mandor where status_aktif order by id_mandor limit 1;
 select id_bank into bank from master_bank where status_aktif limit 1;
 work:=create_fasum_spk_with_wages_atomic('TEST WAGE SETTLEMENT',today,today+30,office,mandor,'[{"nama_pekerjaan":"Retained","bobot":0.5,"volume":10,"satuan":"m","harga_satuan_upah":100},{"nama_pekerjaan":"No retention","bobot":0.5,"volume":10,"satuan":"m","harga_satuan_upah":100}]');
 select jsonb_agg(jsonb_build_object('id_kategori',id_item,'bobot',bobot)) into parents from spk_work_item where id_spk=work;
 select jsonb_agg(jsonb_build_object('group_id',id_item,'urutan',urutan,'nama_pekerjaan',nama_pekerjaan,'bobot',bobot,'volume',volume,'satuan',satuan,'id_mandor',mandor,'retensi',case when nama_pekerjaan='Retained' then .05 else 0 end)) into details from spk_work_item where id_spk=work;
 perform configure_spk_work_atomic(work,'PERINCIAN',2000,parents,details);
 perform activate_spk_atomic(work);
 select jsonb_agg(jsonb_build_object('id_item',d.id_detail,'progress_percent',100)) into entries from spk_work_detail d join spk_work_item w using(id_item) where w.id_spk=work;
 perform insert_work_detail_progress_batch_atomic(work,today,entries);
 select id_progress_detail into a from v_wage_settlement where id_spk=work and nama_pekerjaan='Retained';
 select id_progress_detail into b from v_wage_settlement where id_spk=work and nama_pekerjaan='No retention';
 if (select upah_retensi from v_wage_settlement where id_progress_detail=a)<>50 or (select upah_netto from v_wage_settlement where id_progress_detail=b)<>1000 then raise exception 'Retention snapshot mismatch';end if;
 key:=gen_random_uuid();data:=jsonb_build_object('request_key',key,'jenis','UPAH','tanggal',today,'id_mandor',mandor,'id_bank',bank,'items',jsonb_build_array(jsonb_build_object('id_progress_detail',a,'nominal',500),jsonb_build_object('id_progress_detail',b,'nominal',1000)));
 pay:=create_wage_payment_atomic(data);
 if create_wage_payment_atomic(data)<>pay or (select count(*) from wage_payment where request_key=key)<>1 or (select sisa_upah from v_wage_settlement where id_progress_detail=a)<>450 or (select sisa_upah from v_wage_settlement where id_progress_detail=b)<>0 then raise exception 'Partial payment / duplicate request mismatch';end if;
 failed:=false;begin perform create_wage_payment_atomic(jsonb_set(data,'{items}',jsonb_build_array(jsonb_build_object('id_progress_detail',a,'nominal',1))));exception when others then if sqlerrm like '%KUNCI TRANSAKSI%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Idempotency key reused with different allocations';end if;
 if (select pengeluaran from v_wage_bank_movement where id_pembayaran=pay)<>1500 then raise exception 'Cash movement mismatch';end if;
 data:=jsonb_set(data,'{request_key}',to_jsonb(gen_random_uuid()));failed:=false;begin perform create_wage_payment_atomic(data);exception when others then if sqlerrm like '%MELEBIHI%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Overpayment accepted';end if;
 data:=jsonb_build_object('request_key',gen_random_uuid(),'jenis','RETENSI','tanggal',today,'id_mandor',mandor,'items',jsonb_build_array(jsonb_build_object('id_progress_detail',a,'nominal',25)));
 failed:=false;begin perform create_wage_payment_atomic(data);exception when others then if sqlerrm like '%MENUNGGU%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Open Fasum retention accepted';end if;
 perform deactivate_spk_atomic(work);
 ret:=create_wage_payment_atomic(data);
 if (select retensi_tersedia from v_wage_settlement where id_progress_detail=a)<>25 then raise exception 'Retention reservation mismatch';end if;
 failed:=false;begin perform transition_wage_payment_atomic(ret,'CAIRKAN',today,bank);exception when others then if sqlerrm like '%STATUS%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Unapproved retention paid';end if;
 perform set_config('request.jwt.claim.sub',test_user::text,true);
 failed:=false;begin perform transition_wage_payment_atomic(ret,'SETUJUI');exception when others then if sqlerrm like '%DIREKTUR%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Finance approved retention';end if;
 perform set_config('request.jwt.claim.sub','2d50291d-03e3-46a3-b3d8-c4550bc1bce7',true);
 perform transition_wage_payment_atomic(ret,'SETUJUI');
 perform set_config('request.jwt.claim.sub',test_user::text,true);
 perform transition_wage_payment_atomic(ret,'CAIRKAN',today,bank);
 if (select sisa_retensi from v_wage_settlement where id_progress_detail=a)<>25 or (select pengeluaran from v_wage_bank_movement where id_pembayaran=ret)<>25 then raise exception 'Retention payment mismatch';end if;
 failed:=false;begin perform transition_wage_payment_atomic(ret,'CAIRKAN',today,bank);exception when others then if sqlerrm like '%STATUS%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Duplicate retention payout';end if;
 perform transition_wage_payment_atomic(ret,'BATAL',null,null,'TEST VOID');
 perform transition_wage_payment_atomic(pay,'BATAL',null,null,'TEST VOID');
 if (select sisa_retensi from v_wage_settlement where id_progress_detail=a)<>50 or (select sisa_upah from v_wage_settlement where id_progress_detail=a)<>950 or exists(select 1 from v_wage_bank_movement where id_pembayaran in(pay,ret)) then raise exception 'Cancellation balances mismatch';end if;

 perform set_config('request.jwt.claim.sub','2d50291d-03e3-46a3-b3d8-c4550bc1bce7',true);
 select id_tipe into type_id from master_tipe_rumah where status_aktif limit 1;
 select id_kategori into cat from master_kategori_pekerjaan where status_aktif limit 1;
 insert into master_kavling(id_kavling,blok,no_kavling,id_tipe,status_kavling) values(lot,'TEST',lot,type_id,'AVAILABLE');
 insert into spk(id_kavling,tgl_spk,id_tipe,jenis_bobot,id_kantor,id_mandor,status_spk,tgl_target_selesai,is_active,jenis_spk) values(lot,today,type_id,'CUSTOM',office,mandor,'DRAFT',today+30,false,'KAVLING') returning id_spk into work2;
 insert into spk_work_item(id_spk,urutan,nama_pekerjaan,bobot,id_kategori_legacy) values(work2,1,'TEST CATEGORY',1,cat) returning id_item into parent_id;
 insert into spk_progress_config(id_spk,id_kategori,bobot_final) values(work2,cat,1);
 perform configure_spk_work_atomic(work2,'PERINCIAN',1000,jsonb_build_array(jsonb_build_object('id_kategori',parent_id,'bobot',1)),jsonb_build_array(jsonb_build_object('group_id',parent_id,'urutan',1,'nama_pekerjaan','TEST KAVLING RETENTION','bobot',1,'volume',10,'satuan','m','id_mandor',mandor,'retensi',.05)));
 perform activate_spk_atomic(work2);
 select jsonb_agg(jsonb_build_object('id_item',d.id_detail,'progress_percent',100)) into entries from spk_work_detail d join spk_work_item w using(id_item) where w.id_spk=work2;
 perform insert_work_detail_progress_batch_atomic(work2,today,entries);
 select id_progress_detail into a from v_wage_settlement where id_spk=work2;
 data:=jsonb_build_object('request_key',gen_random_uuid(),'jenis','RETENSI','tanggal',today,'id_mandor',mandor,'items',jsonb_build_array(jsonb_build_object('id_progress_detail',a,'nominal',50)));
 failed:=false;begin perform create_wage_payment_atomic(data);exception when others then if sqlerrm like '%MENUNGGU%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Kavling before akad accepted';end if;
 insert into sales(id_kavling,nama_konsumen,status_sales,jenis_pembayaran,harga_jual,tgl_booking,status_aktif) values(lot,'TEST WAGE AKAD','BOOKING','CASH',0,today,true);
 update sales set status_sales='AKAD',tgl_akad=today,target_akad=today,id_notaris=(select id_notaris from master_notaris where status_aktif limit 1) where id_kavling=lot;
 failed:=false;begin perform create_wage_payment_atomic(data);exception when others then if sqlerrm like '%MENUNGGU%' then failed:=true;else raise;end if;end;if not failed then raise exception 'AKAD kavling with unfinished SPK accepted';end if;
 perform deactivate_spk_atomic(work2);
 if not (select retensi_layak from v_wage_settlement where id_progress_detail=a) then raise exception 'Finished akad Kavling not eligible';end if;
 ret:=create_wage_payment_atomic(data);
 perform transition_wage_payment_atomic(ret,'SETUJUI');
 perform transition_wage_payment_atomic(ret,'CAIRKAN',today,bank);
 if (select sisa_retensi from v_wage_settlement where id_progress_detail=a)<>0 then raise exception 'Kavling after akad retention mismatch';end if;
 perform set_config('request.jwt.claim.sub',test_user::text,true);
 update user_profiles set role='MARKETING' where user_id=auth.uid();
 failed:=false;begin perform create_wage_payment_atomic(jsonb_set(data,'{request_key}',to_jsonb(gen_random_uuid())));exception when others then if sqlerrm like '%DITOLAK%' then failed:=true;else raise;end if;end;if not failed then raise exception 'Unauthorized payment';end if;
 if has_function_privilege('anon','public.create_wage_payment_atomic(jsonb)','execute') or has_table_privilege('authenticated','public.wage_payment','insert') then raise exception 'Direct mutation access';end if;
end $test$;
rollback;
